import smbus2
import logging
import signal
import time

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.bus = smbus2.SMBus(busnum)
        self.debug = debug
        self.last_conversion = None
        self.last_comparator = None
        self._setup()

    def _setup(self):
        try:
            self._read_config()
        except Exception as e:
            logging.error(f"Failed to read config register: {e}")
            raise

    def _read_config(self):
        config = self._read_register(0x00)
        if config & 0x80:
            raise ValueError("ADC not ready")

    def _read_register(self, register):
        try:
            return self.bus.read_byte(self.address, register)
        except Exception as e:
            logging.error(f"Failed to read register {hex(register)}: {e}")
            raise

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            self._start_conversion(channel, pga, sps)
            return self._read_register(0x00) << 8 | self._read_register(0x01)
        except Exception as e:
            logging.error(f"Failed to read ADC conversion: {e}")
            raise

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            self._start_conversion(channel, pga, sps)
            self._set_continuous_mode()
        except Exception as e:
            logging.error(f"Failed to start continuous conversion: {e}")
            raise

    def get_last_conversion_results(self):
        try:
            return self.last_conversion
        except AttributeError:
            return None

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            self._start_conversion(channel, pga, sps)
            self._set_comparator(channel, threshold_high, threshold_low, active_low, traditional_mode, latching, num_readings)
        except Exception as e:
            logging.error(f"Failed to start single-ended comparator: {e}")
            raise

    def _start_conversion(self, channel, pga, sps):
        try:
            self._write_register(0x87, channel << 4 | pga)
            self._write_register(0x88, sps)
        except Exception as e:
            logging.error(f"Failed to start conversion: {e}")
            raise

    def _set_comparator(self, channel, threshold_high, threshold_low, active_low, traditional_mode, latching, num_readings):
        try:
            self._write_register(0x8A, channel << 4 | threshold_high)
            self._write_register(0x8B, channel << 4 | threshold_low)
            self._write_register(0x8C, channel << 4 | (1 if active_low else 0))
            self._write_register(0x8D, 0x01 if traditional_mode else 0x00)
            self._write_register(0x8E, 0x01 if latching else 0x00)
            self._write_register(0x8F, num_readings)
        except Exception as e:
            logging.error(f"Failed to set comparator: {e}")
            raise

    def _set_continuous_mode(self):
        try:
            self._write_register(0x8D, 0x00)
        except Exception as e:
            logging.error(f"Failed to set continuous mode: {e}")
            raise

    def _write_register(self, register, value):
        try:
            return self.bus.write_byte_data(self.address, register, value)
        except Exception as e:
            logging.error(f"Failed to write to register {hex(register)}: {e}")
            raise

    def _read_register(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except Exception as e:
            logging.error(f"Failed to read from register {hex(register)}: {e}")
            raise

    def cleanup(self):
        try:
            self.bus.close()
        except Exception as e:
            logging.error(f"Failed to close I2C bus: {e}")

    def __del__(self):
        self.cleanup()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    try:
        with ADS1015() as adc:
            while True:
                print(adc.read_adc_single_ended())
                time.sleep(0.1)
    except Exception as e:
        logging.error(f"Main loop failed: {e}")

import time
import os
import signal
import sys
import logging
import threading
import gpiozero
from adafruit_dht import DHT22
from adafruit_spi_device import SPI, SPIDevice
from picamera2 import PiCamera2
from paho.m2mqtt import mqtt
import numpy as np

# Set up logging
logging.basicConfig(filename='greenhouse.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO setup
pump = gpiozero.LED(17, initial_value=False)
fan = gpiozero.LED(27, initial_value=False)
light = gpiozero.LED(22, initial_value=False)
led = gpiozero.LED(25, initial_value=False)

# SPI setup
spi = SPI(0, SPICLK=11, SPIMOSI=10, SPIMISO=9, SPICLKfreq=1000000)
cs = SPIDevice(spi, 0, 0, 8, 0)

# DHT22 sensor setup
dht22 = DHT22(spi, 8)

# MCP3008 ADC setup
adc = spi.open(0, 0)

# MQTT setup
mqttc = mqtt.Client()
mqttc.connect("localhost", 1883)
mqttc.loop_start()

# Watchdog timer
watchdog = threading.Event()

def handle_signal(sig, frame):
    if sig in (signal.SIGTERM, signal.SIGINT):
        watchdog.set()
        logging.info("Received signal, exiting.")
        sys.exit(0)

signal.signal(signal.SIGTERM, handle_signal)
signal.signal(signal.SIGINT, handle_signal)

def read_sensor_data():
    while True:
        try:
            temperature, humidity = dht22.humidity, dht22.temperature
            logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
            return temperature, humidity
        except Exception as e:
            logging.error(f"Sensor read failed: {e}")
            logging.info("Retrying sensor read...")
            time.sleep(1)

def read_adc_data():
    while True:
        try:
            value = adc.read(0)
            logging.info(f"ADC value: {value}")
            return value
        except Exception as e:
            logging.error(f"ADC read failed: {e}")
            logging.info("Retrying ADC read...")
            time.sleep(1)

def control_pump(command):
    if command.lower() == 'on':
        pump.on()
        logging.info("Pump turned on")
    elif command.lower() == 'off':
        pump.off()
        logging.info("Pump turned off")
    else:
        logging.error("Invalid pump command")

def control_fan(command):
    if command.lower() == 'on':
        fan.on()
        logging.info("Fan turned on")
    elif command.lower() == 'off':
        fan.off()
        logging.info("Fan turned off")
    else:
        logging.error("Invalid fan command")

def control_light(command):
    if command.lower() == 'on':
        light.on()
        logging.info("Light turned on")
    elif command.lower() == 'off':
        light.off()
        logging.info("Light turned off")
    else:
        logging.error("Invalid light command")

def set_led_status(status):
    if status.lower() == 'online':
        led.on()
        logging.info("LED turned on")
    elif status.lower() == 'offline':
        led.off()
        logging.info("LED turned off")
    elif status.lower() == 'error':
        led.blink(5, 0.2)
        logging.info("LED blinking error")
    elif status.lower() == 'synchronizing':
        led.blink(5, 0.2)
        logging.info("LED blinking synchronizing")
    else:
        logging.error("Invalid LED status")

def read_actuator_commands():
    while True:
        try:
            command = input("Enter command (e.g., pump on/off, fan on/off, light on/off, set LED status): ")
            if command.startswith("control_pump "):
                control_pump(command.split()[1])
            elif command.startswith("control_fan "):
                control_fan(command.split()[1])
            elif command.startswith("control_light "):
                control_light(command.split()[1])
            elif command.startswith("set_led_status "):
                set_led_status(command.split()[1])
            else:
                logging.info("Invalid command")
        except Exception as e:
            logging.error(f"Actuator command read failed: {e}")
            logging.info("Retrying actuator command...")
            time.sleep(1)

def main():
    while True:
        try:
            temperature, humidity = read_sensor_data()
            watchdog.wait()
            if not watchdog.is_set():
                logging.info("Sensor data read successfully")
                read_actuator_commands()
            else:
                logging.info("Watchdog triggered, restarting program")
                os.execv(sys.executable, [sys.executable] + sys.argv)
        except Exception as e:
            logging.error(f"Main loop failed: {e}")
            logging.info("Restarting program")
            os.execv(sys.executable, [sys.executable] + sys.argv)

if __name__ == "__main__":
    main()

import logging
import queue
import time
import argparse
import threading
import RPi.GPIO as GPIO
import spidev
import struct
import numpy as np

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.event_detected = False
        self.debounce_time = 0.1
        self.last_event_time = 0.0

        if self.sensor_type == 'digital':
            if gpio_pins is None or not isinstance(gpio_pins, list) or not all(isinstance(pin, int) for pin in gpio_pins):
                raise ValueError("Invalid gpio_pins for digital sensor")
            GPIO.setmode(GPIO.BCM)
            for pin in gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0b00  # SPI mode 0 (MSB first)
            self.spi.setBitOrder(spidev.SPI.MSB)
            self.spi.writebytes(0b01110000)  # Start bit, single-ended mode, 3 channel-select bits, dummy byte
            self.spi.flush()

        elif self.sensor_type == 'analog':
            if channels is None or not isinstance(channels, list) or not all(isinstance(channel, int) for channel in channels):
                raise ValueError("Invalid channels for analog sensor")
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0b00  # SPI mode 0 (MSB first)
            self.spi.setBitOrder(spidev.SPI.MSB)
            self.spi.writebytes(0b01110000)  # Start bit, single-ended mode, 3 channel-select bits, dummy byte
            self.spi.flush()

        else:
            raise ValueError("Invalid sensor_type")

        self.log_queue = log_queue if log_queue is not None else queue.Queue()

    def run(self):
        while True:
            if self.sensor_type == 'digital':
                if not self.event_detected:
                    GPIO.wait_for_edge(self.gpio_pins[0], GPIO.RISING, timeout=None)
                    self.event_detected = True
                    self.last_event_time = time.time()
                    self.log_queue.put((self.sensor_id, 'sound detected'))
                else:
                    if time.time() - self.last_event_time > self.debounce_time:
                        self.event_detected = False
                        self.log_queue.put((self.sensor_id, 'sound detected'))
                        self.last_event_time = time.time()
            elif self.sensor_type == 'analog':
                try:
                    value = self._read_analog()
                    if value >= self.threshold:
                        self.event_detected = True
                        self.last_event_time = time.time()
                        self.log_queue.put((self.sensor_id, 'sound detected'))
                except Exception as e:
                    logging.error(f"Analog sensor error: {e}")
            else:
                raise ValueError("Invalid sensor_type")

            time.sleep(1 / self.sample_rate)

    def stop(self):
        if self.sensor_type == 'digital':
            GPIO.cleanup()
        elif self.sensor_type == 'analog':
            self.spi.close()

    def _read_analog(self):
        try:
            data = self.spi.readbytes(1)
            value = int.from_bytes(data[0], byteorder='big', signed=False)
            return value
        except Exception as e:
            logging.error(f"Analog sensor error: {e}")
            return 0

def main():
    parser = argparse.ArgumentParser(description='Sound Sensor Monitor')
    parser.add_argument('--sensor_type', type=str, required=True, help='Sensor type (digital/analog)')
    parser.add_argument('--threshold', type=float, required=True, help='Threshold for analog sensor')
    parser.add_argument('--sample_rate', type=int, required=True, help='Sample rate in Hz')
    parser.add_argument('--gpio_pins', type=int, nargs='+', required=False, help='GPIO pins for digital sensor')
    parser.add_argument('--channels', type=int, nargs='+', required=False, help='ADC channels for analog sensor')
    parser.add_argument('--spi_speed', type=int, default=1000000, help='SPI speed in Hz')
    parser.add_argument('--sensor_ids', type=int, nargs='+', required=False, help='Sensor IDs')
    parser.add_argument('--log_file', type=str, default=None, help='Log file path')
    parser.add_argument('--log_queue', type=queue.Queue, default=None, help='Log queue')
    parser.add_argument('--log_level', type=str, default='INFO', help='Log level (DEBUG/INFO/WARNING/ERROR/CRITICAL)')
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file if args.log_file else None, level=args.log_level)

    sensors = []
    for sensor_id in args.sensor_ids:
        if args.sensor_type == 'digital':
            if args.gpio_pins is None or not isinstance(args.gpio_pins, list) or not all(isinstance(pin, int) for pin in args.gpio_pins):
                raise ValueError("Invalid gpio_pins for digital sensor")
            sensors.append(SoundSensor(sensor_id, 'digital', args.threshold, args.sample_rate, args.gpio_pins, None, args.spi_speed, None))
        elif args.sensor_type == 'analog':
            if args.channels is None or not isinstance(args.channels, list) or not all(isinstance(channel, int) for channel in args.channels):
                raise ValueError("Invalid channels for analog sensor")
            sensors.append(SoundSensor(sensor_id, 'analog', args.threshold, args.sample_rate, None, args.channels, args.spi_speed, None))
        else:
            raise ValueError("Invalid sensor_type")

    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        thread.daemon = True
        thread.start()

    try:
        while True:
            pass
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()

if __name__ == "__main__":
    main()

import spidev
import time
import sys
import signal

class GasSensor:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.mode = 0b00  # SPI mode 0
        self.spi.bits_per_word = 8
        self.spi.max_speed_hz = 500000
        self.spi.select = 0
        self.spi = spidev.SpiDev(0, 0)
        self.spi.open(0)
        self.spi.max_speed_hz = 500000
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def read_adc(self, channel):
        try:
            self.spi.xfer2([0b10000000, 0b00000000, (channel << 4) | 0b00000001])
            return sum(self.spi.readbytes(3)) >> 1
        except OSError as e:
            print(f"SPI error: {e}")
            sys.exit(1)

    def convert_to_ppm(self, raw):
        if raw == 0:
            return 0
        voltage = (raw / 1023) * 3.3
        ppm = voltage * 200
        return int(ppm)

    def alert_level(self, ppm):
        if ppm < 150:
            return "safe"
        elif 150 <= ppm <= 399:
            return "warning"
        else:
            return "danger"

    def sample_gas(self):
        for _ in range(12):
            raw = self.read_adc(0)
            ppm = self.convert_to_ppm(raw)
            level = self.alert_level(ppm)
            print(f"Reading: {raw} -> {ppm} ppm -> {level}")
            time.sleep(0.5)

    def cleanup(self):
        self.spi.close()

def signal_handler(sig, frame):
    print("SIGINT or SIGTERM received, exiting...")
    sensor.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    sensor = GasSensor()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    sensor.sample_gas()

import os
import time
import sqlite3
import logging
import signal
import sys
import board
import busio
import digitalio
from adafruit_bmp280_i2c import BMP280_I2C
from adafruit_bme280_i2c import BME280_I2C
from adafruit_ms8607_i2c import MS8607_I2C
from config import Config
from datetime import datetime
import json

# Configure logging
logging.basicConfig(filename='error.log', level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Define sensor types and their addresses
sensor_types = {
    'BMP280': 0x76,
    'BME280': 0x76,
    'MS8607': 0x78
}

# Define sensor IDs
sensor_ids = {
    'BMP280': 0x58,
    'BME280': 0x60,
    'MS8607': 0x60
}

# Define valid sensor ranges
pressure_range = (70000, 110000)
temperature_range = (-20, 50)
humidity_range = (0, 100)

# Define database connection
conn = None
cursor = None

def init_database():
    global conn, cursor
    conn = sqlite3.connect('wildlife_data.db')
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS sensor_data (
            id INTEGER PRIMARY KEY,
            timestamp TEXT,
            sensor_type TEXT,
            sensor_id INTEGER,
            pressure_pa REAL,
            temperature_c REAL,
            humidity_percent REAL
        )
    ''')
    conn.commit()

def handle_signal(sig, frame):
    global conn, cursor
    if conn:
        conn.close()
    if cursor:
        cursor.close()
    sys.exit(0)

def load_config():
    config_path = os.path.join(os.path.dirname(__file__), 'config.txt')
    if not os.path.exists(config_path):
        logger.error(f"Missing config file at {config_path}")
        return None
    with open(config_path, 'r') as f:
        config = json.load(f)
    return Config(config)

def find_sensors():
    sensors = []
    for sensor_type, address in sensor_types.items():
        for sensor_id in sensor_ids.values():
            try:
                sensor = get_sensor(sensor_type, address, sensor_id)
                sensors.append(sensor)
            except Exception as e:
                logger.error(f"Failed to find {sensor_type} at {address} with ID {sensor_id}: {e}")
    return sensors

def get_sensor(sensor_type, address, sensor_id):
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = None
        if sensor_type == 'BMP280':
            sensor = BMP280_I2C(i2c, address=address)
        elif sensor_type == 'BME280':
            sensor = BME280_I2C(i2c, address=address)
        elif sensor_type == 'MS8607':
            sensor = MS8607_I2C(i2c, address=address)
        else:
            raise ValueError(f"Unknown sensor type {sensor_type}")
        if sensor_id != sensor.get_id():
            raise ValueError(f"Expected sensor ID {sensor_id} for {sensor_type} at {address}")
        return sensor
    except Exception as e:
        raise RuntimeError(f"Failed to initialize {sensor_type} at {address} with ID {sensor_id}: {e}")

def read_sensor(sensor):
    try:
        pressure_pa = sensor.read_pressure()
        temperature_c = sensor.read_temperature()
        humidity_percent = sensor.read_humidity() if sensor_type == 'BME280' or sensor_type == 'MS8607' else None
        return pressure_pa, temperature_c, humidity_percent
    except Exception as e:
        raise RuntimeError(f"Failed to read sensor {sensor_type} at {address}: {e}")

def validate_data(pressure_pa, temperature_c, humidity_percent):
    if pressure_pa is None or not pressure_pa_range(pressure_pa):
        return False
    if temperature_c is None or not temperature_range(temperature_c):
        return False
    if humidity_percent is not None and not humidity_range(humidity_percent):
        return False
    return True

def pressure_range(pressure_pa):
    return pressure_pa >= pressure_range[0] and pressure_pa <= pressure_range[1]

def temperature_range(temperature_c):
    return temperature_c >= temperature_range[0] and temperature_c <= temperature_range[1]

def humidity_range(humidity_percent):
    return humidity_percent >= humidity_range[0] and humidity_percent <= humidity_range[1]

def store_data(pressure_pa, temperature_c, humidity_percent):
    global conn, cursor
    if conn and cursor:
        cursor.execute('INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent) VALUES (?, ?, ?, ?, ?, ?)', 
                       (datetime.now().isoformat(), sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent))
        conn.commit()

def main():
    signal.signal(signal.SIGINT, handle_signal)
    config = load_config()
    if not config:
        return 1
    sensors = find_sensors()
    if not sensors:
        return 0
    sampling_interval = config.sampling_interval_seconds
    init_database()
    while True:
        for sensor in sensors:
            sensor_type = sensor.__class__.__name__
            sensor_id = sensor.get_id()
            pressure_pa, temperature_c, humidity_percent = read_sensor(sensor)
            if not validate_data(pressure_pa, temperature_c, humidity_percent):
                logger.warning(f"Invalid data for {sensor_type} at {sensor_id}: {pressure_pa}, {temperature_c}, {humidity_percent}")
                continue
            store_data(pressure_pa, temperature_c, humidity_percent)
        time.sleep(sampling_interval)

if __name__ == "__main__":
    sys.exit(main())

import time
import signal
import sys
import random
import board
import busio
import adafruit_amg88xx
import adafruit_i2c
import gpiozero
import threading

# Initialize I2C bus
i2c = busio.I2C(board.I2C(), addr=0x69)

# Initialize AMG8833 sensor
try:
    amg = adafruit_amg88xx.AMG8833(i2c)
except Exception as e:
    print(f"AMG8833 sensor not found: {e}")
    amg = None

# Initialize buzzer
try:
    buzzer = gpiozero.Buzzer(board.GPIO17)
except Exception as e:
    print(f"Buzzer not found: {e}")
    buzzer = None

def detect_human(thermal_data):
    """Check if any pixel in the thermal frame exceeds 30°C."""
    for row in thermal_data:
        for pixel in row:
            if pixel > 30:
                return True
    return False

def trigger_alert(buzzer):
    """Sound the buzzer for exactly 1 second."""
    if buzzer:
        buzzer.on()
        time.sleep(1)
        buzzer.off()

def main():
    """Main loop."""
    thermal_data = [[random.randint(20, 45) for _ in range(8)] for _ in range(8)]
    while True:
        try:
            if amg:
                thermal_data = [[amg[0][y][x] for x in range(8)] for y in range(8)]
            if detect_human(thermal_data):
                print("Human detected!")
                trigger_alert(buzzer)
            else:
                print("No human detected.")
        except Exception as e:
            print(f"Error: {e}")
            thermal_data = [[random.randint(20, 45) for _ in range(8)] for _ in range(8)]
        print("Status: Running")
        time.sleep(0.1)

def signal_handler(sig, frame):
    """Signal handler to clean up resources."""
    if amg:
        amg.close()
    if buzzer:
        buzzer.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == "__main__":
    main()

