except Exception as e:
    logging.error("Camera initialization failed: %s", e)
    camera = None

# Voice recognition setup
def voice_recognition():
    r = sr.Recognizer()
    with sr.Microphone() as source:
        r.adjust_for_ambient_noise(source, 1)
        print("Listening...")
        try:
            audio = r.listen(source, timeout=5)
            print("Recognizing...")
            try:
                command = r.recognize_google(audio)
                if command.startswith("Greenhouse"):
                    command = command[9:]
                    if command == "turn on the lights":
                        turn_lights_on()
                    elif command == "turn off the lights":
                        turn_lights_off()
                    elif command == "what is the temperature":
                        print_temperature()
                    elif command == "take a picture":
                        take_picture()
            except sr.UnknownValueError:
                logging.error("Google Speech Recognition could not understand audio")
            except sr.RequestError as e:
                logging.error("Could not request results from Google Speech Recognition service: %s", e)
        except sr.WaitTimeoutError:
            logging.info("No voice command detected")

# Signal handlers
def signal_handler(sig, frame):
    logging.info("Received signal. Exiting.")
    GPIO.cleanup()
    if camera:
        camera.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Functions
def turn_lights_on():
    if GPIO:
        GPIO.output(17, True)
    else:
        logging.info("Lights turned on (simulated).")

def turn_lights_off():
    if GPIO:
        GPIO.output(17, False)
    else:
        logging.info("Lights turned off (simulated).")

def print_temperature():
    if dht:
        temperature, humidity = dht.read()
        if temperature is None:
            logging.error("DHT11 sensor failed to read. Simulated temperature.")
            temperature = simulated_dht_read()[0]
        print(f"Temperature: {temperature}°C, Humidity: {humidity}%")
    else:
        logging.info("Temperature not available (simulated).")
        print("Simulated temperature: 25.5°C")

def take_picture():
    if camera:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        camera.capture(f"greenhouse_{timestamp}.jpg")
        logging.info("Picture taken: greenhouse_{timestamp}.jpg")
    else:
        logging.info("Picture not taken (simulated).")

def voice_command_loop():
    while True:
        voice_recognition()

# Main loop
