import sys
import time
import csv
import picamera
from picamera import PiCameraMjpegStream
from gpiozero import InputDevice
from datetime import datetime
import paho.mqtt.client as mqtt
import os

# Configuration
GPIO_PINS = [17, 27, 22]
LOG_FILE = "/home/pi/vibration_data.csv"
INTERVAL = 5.0
CALIBRATION_DURATION = 60
PICTURE_INTERVAL = 60
PULL_DOWN = GPIO.PUD_DOWN

# GPIO setup
def setup_gpio(pins):
    try:
        for pin in pins:
            GPIO.setup(pin, GPIO.IN, pull_up_down=PULL_DOWN)
    except Exception as e:
        print(f"GPIO setup error: {e}")
        return False
    return True

# Calibration
def calibrate(pins, duration):
    try:
        baseline = []
        for pin in pins:
            print(f"Calibrating pin {pin}...")
            start = time.time()
            count = 0
            while (time.time() - start) < duration:
                if GPIO.input(pin):
                    count += 1
                time.sleep(INTERVAL)
            baseline.append(count / duration * 100 + 20)
            print(f"Baseline for pin {pin}: {baseline[-1]}%")
        return baseline
    except Exception as e:
        print(f"Calibration error: {e}")
        return None

# Monitoring
def monitor(pins, baseline, log_file):
    try:
        with open(log_file, 'w', newline='', encoding='utf-8') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(["Timestamp", "Sensor1", "Sensor2", "Sensor3"])
            while True:
                try:
                    now = datetime.now().isoformat(sep=' ', microsecond=True)
                    data = []
                    for pin in pins:
                        count = 0
                        start = time.time()
                        while (time.time() - start) < INTERVAL:
                            if GPIO.input(pin):
                                count += 1
                            time.sleep(INTERVAL)
                        data.append(count / INTERVAL * 100)
                    for i, sensor in enumerate(data):
                        if sensor > baseline[i]:
                            data[i] = 1
                        else:
                            data[i] = 0
                    writer.writerow([now, *data])
                    print(f"Logged: {now}, {data}")
                except Exception as e:
                    print(f"Logging error: {e}")
                    if not os.path.exists(log_file):
                        print(f"File {log_file} does not exist. Falling back to console logging.")
                        with open(log_file, 'w', newline='', encoding='utf-8') as csvfile:
                            writer = csv.writer(csvfile)
                            writer.writerow(["Timestamp", "Sensor1", "Sensor2", "Sensor3"])
                            writer.writerow([now, *data])
                    else:
                        print(f"File {log_file} exists. Continuing with console logging.")
                        print(f"{now}, {data}")
                time.sleep(INTERVAL)
    except KeyboardInterrupt:
        print("Shutting down...")
    except Exception as e:
        print(f"Monitoring error: {e}")

# Image capture
def capture_images(pins, picture_interval):
    try:
        camera = PiCameraMjpegStream(resolution=(640, 480), framerate=30)
        camera.start()
        images_dir = os.path.join(os.getcwd(), 'images')
        if not os.path.exists(images_dir):
            os.makedirs(images_dir)
        while True:
            try:
                now = datetime.now().isoformat(sep=' ', microsecond=True)
                filename = os.path.join(images_dir, f"{now}.jpg")
                camera.start_recording(filename, use_video_port=True)
                camera.wait_recording(picture_interval)
                camera.stop_recording()
                print(f"Captured image: {filename}")
            except Exception as e:
                print(f"Image capture error: {e}")
                camera.stop()
    except Exception as e:
        print(f"Camera initialization error: {e}")

# MQTT client
def mqtt_client(log_file):
    try:
        client = mqtt.Client()
        client.connect("localhost", 1883, 60)
        client.loop_start()
        while True:
            try:
                with open(log_file, 'r') as csvfile:
                    reader = csv.reader(csvfile)
                    for row in reader:
                        client.publish("vibration", json.dumps(row))
            except Exception as e:
                print(f"Mqtt client error: {e}")
    except Exception as e:
        print(f"Mqtt client initialization error: {e}")

# Main
def main():
    if len(sys.argv) < 2:
        print("Usage: python script.py -g <gpio1> <gpio2> <gpio3> -l <log_file> -i <interval> -c <calibration_duration> -p <picture_interval>")
        return

    args = sys.argv[1:]
    if not all(arg in args for arg in ["-g", "-l", "-i", "-c", "-p"]):
        print("Invalid arguments. Please use -g <gpio1> <gpio2> <gpio3> -l <log_file> -i <interval> -c <calibration_duration> -p <picture_interval>")
        return

    try:
        gpio_pins = list(map(int, [arg for arg in args if arg.startswith("-g")][0].split()[1:]))
        log_file = args[args.index("-l") + 1]
        interval = float(args[args.index("-i") + 1])
        calibration_duration = int(args[args.index("-c") + 1])
        picture_interval = int(args[args.index("-p") + 1])
    except (IndexError, ValueError):
        print("Invalid arguments. Please use -g <gpio1> <gpio2> <gpio3> -l <log_file> -i <interval> -c <calibration_duration> -p <picture_interval>")
        return

    if not setup_gpio(gpio_pins):
        return

    baseline = calibrate(gpio_pins, calibration_duration)
    if baseline is None:
        return

    monitor(gpio_pins, baseline, log_file)

    # Optional: Start image capture
    # capture_images(gpio_pins, picture_interval)

    # Optional: Start MQTT client
    # mqtt_client(log_file)

if __name__ == "__main__":
