import cv2
import numpy as np
import pygame
import signal
import sys
import time
import os
import threading
from gpiozero import Button, OutputDevice
from face_detection import FaceDetector
from config import Config
from cv2.face import EigenFaceRecognizer_create

class Door:
    def __init__(self, pin, model_path):
        self.button = Button(pin)
        self.lock = OutputDevice(17, initial_value=1)
        self.model_path = model_path
        self.is_locked = self.lock.value

    def lock(self):
        self.lock.value = 0

    def unlock(self):
        self.lock.value = 1

    def is_locked(self):
        return self.lock.value

    def cleanup(self):
        self.lock.close()
        self.button.close()

    def is_button_up(self):
        return self.button.value

class FaceRecognizer:
    def __init__(self, model_path, positive_label, positive_threshold):
        self.model = EigenFaceRecognizer_create()
        self.model.load(model_path)
        self.positive_label = positive_label
        self.positive_threshold = positive_threshold

    def recognize(self, face):
        try:
            label, confidence = self.model.predict(face)
            return label == self.positive_label and confidence < self.positive_threshold
        except Exception as e:
            print(f"Error during face recognition: {e}")
            return False

def main():
    config = Config()
    face_detector = FaceDetector(config.get_camera())
    door = Door(config.get_button_pin(), config.get_training_file())
    face_recognizer = FaceRecognizer(config.get_training_file(), config.get_positive_label(), config.get_positive_threshold())
    pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
    channels = [pygame.mixer.Channel(i) for i in range(3)]
    welcome = channels[0].play(pygame.mixer.Sound(config.get_welcome_sound_path()))
    wait = channels[1].play(pygame.mixer.Sound(config.get_wait_sound_path()))
    later = channels[2].play(pygame.mixer.Sound(config.get_later_sound_path()))

    def handle_keypress(event):
        if event.key == pygame.K_l and event.type == pygame.KEYDOWN:
            door.lock()

    def handle_sigint(sig, frame):
        door.cleanup()
        pygame.mixer.quit()
        sys.exit(0)

    signal.signal(signal.SIGINT, handle_sigint)
    signal.signal(signal.SIGTERM, handle_sigint)

    try:
        while True:
            door.button.wait_for_press(0.1)
            if door.is_button_up():
                face = face_detector.detect_single()
                if face is not None:
                    face = face_detector.crop(face)
                    face = face_detector.resize(face, (112, 112))
                    if face_recognizer.recognize(face):
                        door.unlock()
                        channels[0].play(pygame.mixer.Sound(config.get_welcome_sound_path()))
                    else:
                        channels[2].play(pygame.mixer.Sound(config.get_later_sound_path()))
                        channels[1].play(pygame.mixer.Sound(config.get_wait_sound_path()))
                else:
                    print("No face detected")
            else:
                time.sleep(0.1)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        door.cleanup()
        pygame.mixer.quit()

if __name__ == "__main__":
    main()

import logging
import threading
import io
import picamera2
import cv2
import paho.mqtt.client as mqtt
import websocket
import time
import signal
import sys

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraStreamBuffer:
    def __init__(self, websocket_handler, camera):
        self.lock = threading.Lock()
        self.buffer = io.BytesIO()
        self.websocket_handler = websocket_handler
        self.camera = camera
        self.frame = None

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            if b'\xff\xd8' in self.buffer.getvalue():
                self.frame = self.buffer.getvalue()
                self.buffer.truncate()
                self.buffer.seek(0)
                self.flush()

    def flush(self):
        with self.lock:
            if self.frame is not None:
                try:
                    self.frame = self._convert_to_opencv_frame(self.frame)
                    self.websocket_handler.broadcast(self.frame)
                except Exception as e:
                    logging.error(f"Error broadcasting frame: {e}")
                self.frame = None

    def _convert_to_opencv_frame(self, frame_data):
        try:
            return cv2.imdecode(np.frombuffer(frame_data, dtype=np.uint8), cv2.IMREAD_COLOR)
        except Exception as e:
            logging.error(f"Error decoding JPEG frame: {e}")
            return None

class MotionDetectionBuffer:
    def __init__(self, websocket_handler, camera):
        self.lock = threading.Lock()
        self.buffer = io.BytesIO()
        self.websocket_handler = websocket_handler
        self.camera = camera
        self.frame = None
        self.previous_frame = None
        self.current_frame = None

    def write(self, data):
        with self.lock:
            self.buffer.write(data)
            if b'\xff\xd8' in self.buffer.getvalue():
                self.frame = self.buffer.getvalue()
                self.buffer.truncate()
                self.buffer.seek(0)
                self.flush()

    def flush(self):
        with self.lock:
            if self.frame is not None:
                try:
                    self.frame = self._convert_to_opencv_frame(self.frame)
                    self.previous_frame = self.current_frame
                    self.current_frame = self.frame
                    self.detect_motion()
                except Exception as e:
                    logging.error(f"Error flushing frame: {e}")
                self.frame = None

    def detect_motion(self):
        if self.previous_frame is not None and self.current_frame is not None:
            try:
                self.detect_motion_function(self.previous_frame, self.current_frame)
            except Exception as e:
                logging.error(f"Error detecting motion: {e}")

    def _convert_to_opencv_frame(self, frame_data):
        try:
            return cv2.imdecode(np.frombuffer(frame_data, dtype=np.uint8), cv2.IMREAD_COLOR)
        except Exception as e:
            logging.error(f"Error decoding JPEG frame: {e}")
            return None

class CameraStreamer:
    def __init__(self, websocket_handler, camera):
        self.camera = camera
        self.camera.start()
        self.camera_buffer = CameraStreamBuffer(websocket_handler, camera)
        self.motion_buffer = MotionDetectionBuffer(websocket_handler, camera)

    def __del__(self):
        self.camera.stop()
        self.camera_buffer.flush()
        self.motion_buffer.flush()

    def run(self):
        try:
            while True:
                self.camera.capture_buffer.write(self.camera_buffer.write)
                self.motion_buffer.write(self.camera_buffer.write)
        except Exception as e:
            logging.error(f"Error capturing frames: {e}")
        finally:
            self.camera.stop()
            self.camera_buffer.flush()
            self.motion_buffer.flush()

class WebSocketHandler:
    def __init__(self):
        self.connections = 0

    def has_connections(self):
        return self.connections > 0

    def broadcast(self, data):
        self.connections += 1
        websocket_client = websocket.WebSocketClient('ws://localhost:8080')
        websocket_client.connect('ws://localhost:8080')
        websocket_client.send(data)
        websocket_client.close()
        self.connections -= 1

def signal_handler(sig, frame):
    logging.info("Received signal, shutting down.")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = picamera2.PiCamera2(resolution=(640, 480), framerate=10, format='JPEG')
    camera.resolution = (640, 480)
    camera.framerate = 10
    camera.format = 'JPEG'

    websocket_handler = WebSocketHandler()

    camera_streamer = CameraStreamer(websocket_handler, camera)
    camera_streamer.run()

import smbus
import time
import sys

# Initialize the I2C bus
try:
    bus = smbus.SMBus(1)
except IOError as e:
    print(f"I2C bus error: {e}")
    sys.exit(1)

# Define the address and port expander configuration
I2C_ADDR = 0x20
PORT_REG = 0x00  # Output port register
INPUT_REG = 0x01  # Input port register

# Function to read the output port register
def read_output_port():
    try:
        return bus.read_byte(I2C_ADDR, PORT_REG)
    except IOError as e:
        print(f"Error reading output port register: {e}")
        return None

# Function to read the input port register
def read_input_port():
    try:
        return bus.read_byte(I2C_ADDR, INPUT_REG)
    except IOError as e:
        print(f"Error reading input port register: {e}")
        return None

# Function to print obstacle detections
def print_obstacle_detections(port_states):
    for i in range(8):
        if port_states[i] == 0:
            print(f"Obstacle detected by sensor {i}")

# Main loop
while True:
    try:
        # Read the output port register
        port_states = [((port_states >> i) & 1) for i in range(8)]
        print_obstacle_detections(port_states)
        time.sleep(0.1)  # Poll every 100 ms
    except KeyboardInterrupt:
        print("Exiting...")
        break
    except Exception as e:
        print(f"An error occurred: {e}")
        time.sleep(1)  # Pause for 1 second and retry

