import time
import random
import logging
import sys
import signal
from rpi.gpio import GPIO, Direction, Speed, PWM
from rpi.gpio import Pin, PinState

SERVO_PIN_1 = 17
SERVO_PIN_2 = 18

# Set up logging
logging.basicConfig(filename='greenhouse_vent.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def init_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        return GPIO, GPIO.PWM(SERVO_PIN_1, 50), GPIO.PWM(SERVO_PIN_2, 50)
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        sys.exit(1)

def move_servo(pwm, angle):
    try:
        duty = (angle / 180.0) * 0.125 + 0.025
        pwm.ChangeDutyCycle(duty)
        time.sleep(0.1)
    except Exception as e:
        logging.error(f"Servo movement failed: {e}")
        sys.exit(1)

def main():
    GPIO, servo1, servo2 = init_gpio()
    failure_count = 0
    failure_servo = None

    while True:
        try:
            temperature = random.uniform(15, 35)
            logging.info(f"Temperature: {temperature}°C")

            if temperature < 20:
                angle = 0
            elif temperature < 25:
                angle = 45
            elif temperature < 30:
                angle = 90
            elif temperature < 35:
                angle = 135
            else:
                angle = 180

            if failure_count == 0:
                if random.random() < 0.1:
                    failure_count += 1
                    failure_servo = servo1
                    logging.warning(f"Servo1 failure detected")
                else:
                    move_servo(servo1, angle)
            else:
                move_servo(failure_servo, angle)
                failure_count = 0
                failure_servo = None

            if failure_count > 2:
                logging.info("Switching to Servo2 permanently")
                failure_servo = servo2

            if failure_count > 0:
                logging.info(f"Servo1 failure count: {failure_count}")

            move_servo(servo2, angle if failure_count > 0 else 0)

            time.sleep(5)
        except KeyboardInterrupt:
            logging.info("Program interrupted by user")
            GPIO.cleanup()
            servo1.stop()
            servo2.stop()
            sys.exit(0)
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            GPIO.cleanup()
            servo1.stop()
            servo2.stop()
            sys.exit(1)

if __name__ == "__main__":
    main()

import time
import socket
import logging
import struct
import sys
import signal
from gpiozero import GPIODevice, InputDevice, DigitalOutputDevice
from dht22 import DHT22

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize GPIO devices
dht22 = DHT22(pin=4)
led = DigitalOutputDevice(17, initial_value=1)

# Define control LED function
def control_led(temperature):
    if temperature > 30.0:
        led.value = 0
    elif temperature < 27.0:
        led.value = 1
    else:
        led.value = led.value  # No change

# Define send_data function
def send_data(temperature, humidity):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            sock.connect(('192.168.1.100', 12345))
            sock.sendall(f"{temperature:.1f},{humidity:.1f}".encode())
    except Exception as e:
        logging.error(f"Failed to send data: {e}")

# Define read_dht22 function
def read_dht22():
    try:
        dht22.trigger()
        data = dht22.read()
        if data is None:
            return (25.0, 50.0)
        humidity = data.humidity
        temperature = data.temperature
        checksum = data.checksum
        if checksum != (temperature + humidity) & 0xFF:
            return (25.0, 50.0)
        return (temperature, humidity)
    except Exception as e:
        logging.error(f"Failed to read DHT22: {e}")
        return (25.0, 50.0)

# Define main loop
def main():
    try:
        while True:
            temperature, humidity = read_dht22()
            control_led(temperature)
            logging.info(f"{time.strftime('%Y-%m-%d %H:%M:%S')}, {temperature:.1f}, {humidity:.1f}, {led.value}")
            send_data(temperature, humidity)
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Shutting down...")
        dht22.close()
        led.close()
        sys.exit(0)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        dht22.close()
        led.close()
        sys.exit(1)

# Register signal handler for Ctrl+C
def signal_handler(sig, frame):
    logging.info("Received Ctrl+C signal, shutting down...")
    sys.exit(0)

# Register signal handler
signal.signal(signal.SIGINT, signal_handler)

# Run main loop
if __name__ == "__main__":
    main()

import serial
import time
import csv
import sys
import datetime
import paho.mqtt.publish as publish
import signal

def handle_serial_port_open_error():
    print("Error: Unable to open serial port /dev/ttyACM0.", file=sys.stderr)
    sys.exit(1)

def handle_serial_port_closed():
    print("Serial port closed.", file=sys.stderr)
    sys.exit(0)

def handle_serial_timeout():
    print("Serial timeout occurred.", file=sys.stderr)
    sys.exit(1)

def handle_keyboard_interrupt():
    print("Keyboard interrupt received. Closing serial port and exiting.", file=sys.stderr)
    sys.exit(0)

def main():
    try:
        ser = serial.Serial('/dev/ttyACM0', 115200, timeout=1)
    except serial.SerialException as e:
        handle_serial_port_open_error()

    def read_serial():
        try:
            line = ser.readline().decode('ascii').strip()
            if line:
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                celsius = float(line)
                fahrenheit = celsius * 9/5 + 32
                yield (timestamp, celsius, fahrenheit)
        except serial.SerialTimeoutError:
            handle_serial_timeout()
        except Exception as e:
            print(f"Error reading from serial port: {e}", file=sys.stderr)

    def write_to_csv(data):
        try:
            with open('temperature_log.csv', 'a', newline='') as csvfile:
                writer = csv.writer(csvfile)
                if not csvfile.tell() == 0:
                    writer.writerow(['timestamp', 'celsius', 'fahrenheit'])
                writer.writerow(data)
        except Exception as e:
            print(f"Error writing to CSV: {e}", file=sys.stderr)

    def write_to_mqtt(data):
        try:
            publish.single("temperature", json.dumps(data), hostname="localhost", port=1883, retain=True)
        except Exception as e:
            print(f"Error publishing to MQTT: {e}", file=sys.stderr)

    def signal_handler(sig, frame):
        handle_keyboard_interrupt()

    signal.signal(signal.SIGINT, handle_keyboard_interrupt)
    signal.signal(signal.SIGTERM, handle_serial_port_closed)

    try:
        for timestamp, celsius, fahrenheit in read_serial():
            write_to_csv([timestamp, celsius, fahrenheit])
            write_to_mqtt([timestamp, celsius, fahrenheit])
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
        sys.exit(1)

    ser.close()

if __name__ == "__main__":
    main()

import smbus2
import time
import logging
import sys
import signal
import contextlib

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20Sensor:
    def __init__(self):
        self._smbus = smbus2.SMBus(1)
        self._temperature = None
        self._humidity = None
        self._last_measurement = None
        self._measurement_attempts = 0
        self._measurement_timeout = 0.01
        self._measurement_interval = 0.02
        self._measurement_max_attempts = 5
        self._measurement_retry_delay = 0.01
        self._measurement_timeout_duration = 0.8
        self._measurement_interval_duration = 0.08
        self._measurement_attempts_remaining = 0
        self._measurement_status = None
        self._measurement_result = None
        self._measurement_result_cashed = False

    def begin(self):
        try:
            self._smbus = smbus2.SMBus(1)
            time.sleep(0.5)
            self._smbus.write_byte(0x38, 0x71)
            status = self._smbus.read_byte(0x38)
            if (status & 0x18) != 0x18:
                logging.error("DHT20 sensor not ready or error occurred")
                return False
            return True
        except OSError as e:
            logging.error(f"Error initializing DHT20 sensor: {e}")
            return False

    def get_temperature_and_humidity(self):
        if self._measurement_result_cashed:
            return self._temperature, self._humidity
        if self._last_measurement is not None:
            return self._temperature, self._humidity
        if time.time() - self._last_measurement < self._measurement_interval:
            return self._temperature, self._humidity
        self._measurement_result_cashed = False
        self._measurement_result = None
        self._measurement_attempts_remaining = self._measurement_max_attempts
        self._measurement_status = None
        self._measurement_result_cashed = False
        self._last_measurement = time.time()
        return self._temperature, self._humidity

    def close(self):
        try:
            self._smbus.close()
        except OSError as e:
            logging.error(f"Error closing DHT20 sensor: {e}")

    @contextlib.contextmanager
    def __enter__(self):
        self.begin()
        try:
            yield self
        finally:
            self.close()

    @contextlib.contextmanager
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def _read_data(self, address, register, timeout=0.1):
        try:
            self._smbus.write_byte(address, register)
            time.sleep(0.0001)
            return self._smbus.read_i2c_block_data(address, register, 7)
        except OSError as e:
            logging.warning(f"Timeout or I2C error reading from DHT20 sensor: {e}")
            return None

    def _check_crc(self, data):
        if data is None:
            return False
        crc = 0xFF
        for byte in data[:6]:
            crc ^= byte
            crc = (crc << 8) | (crc >> 8) & 0xFF
            crc ^= 0x31
        return crc == data[6]

    def _measure(self):
        self._measurement_attempts_remaining -= 1
        self._measurement_status = "busy"
        data = self._read_data(0x38, 0xAC)
        if data is None:
            self._measurement_status = "timeout"
            return
        if not self._check_crc(data):
            self._measurement_status = "crc mismatch"
            return
        self._measurement_status = "idle"
        humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
        humidity = humidity_raw / 2**20 * 100
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
        temperature = temperature_raw / 2**19 * 200 - 50
        self._temperature = temperature
        self._humidity = humidity
        self._measurement_result = (temperature, humidity)
        self._measurement_result_cashed = True

    def _poll(self):
        while self._measurement_attempts_remaining > 0:
            data = self._read_data(0x38, 0x71)
            if data is None:
                self._measurement_status = "timeout"
                return
            if (data & 0x80) == 0:
                self._measurement_status = "idle"
                return
            self._measurement_attempts_remaining -= 1
            time.sleep(self._measurement_interval_duration)
        self._measurement_status = "busy"

    def _retry(self):
        if self._measurement_status == "busy":
            self._poll()
        elif self._measurement_status == "timeout":
            self._measurement_attempts_remaining = self._measurement_max_attempts
            self._poll()
        elif self._measurement_status == "crc mismatch":
            self._measurement_attempts_remaining = self._measurement_max_attempts
            self._poll()

    def _demo_loop(self):
        while True:
            try:
                self._retry()
                if self._measurement_status == "idle":
                    self._measure()
                    print(f"Temperature: {self._temperature:.1f}°C, Humidity: {self._humidity:.1f}%")
            except KeyboardInterrupt:
                logging.info("Demo loop interrupted")
                break
            except SystemExit:
                logging.info("Demo loop exited")
                break
            except Exception as e:
                logging.error(f"Demo loop error: {e}")

if __name__ == "__main__":
    with DHT20Sensor() as sensor:
        sensor.begin()
        sensor._demo_loop()

