import pigpio
import threading
import signal
import sys
import time

class OutputPin:
    def __init__(self, pin, value_list):
        self.pin = pin
        self.value_list = value_list
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise RuntimeError("pigpio.pi() failed to connect to the Pi")
        if pin < 0 or pin > 31:
            raise ValueError("Invalid GPIO pin number")
        if value_list[0] not in (0, 1):
            raise ValueError("Invalid initial value in value_list")
        self.pi.set_mode(pin, pigpio.INPUT if value_list[0] == 0 else pigpio.OUTPUT)
        self.pi.set_pull_up_down(pin, pigpio.PUD_OFF)
        self.value = value_list[0]
        self.lock = threading.Lock()

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError("Invalid value in value_list")
        with self.lock:
            self.pi.write(self.pin, value)
            self.value = value

    def shutdown(self):
        self.pi.set_mode(self.pin, pigpio.INPUT)
        self.pi.set_pull_up_down(self.pin, pigpio.PUD_OFF)
        self.pi.set_mode(self.pin, pigpio.INPUT)
        self.pi.set_pull_up_down(self.pin, pigpio.PUD_OFF)
        self.pi.stop()

class TriggerPin(OutputPin):
    def __init__(self, pin, pulse_duration, pulse_high=True, value_list=(0, 1)):
        super().__init__(pin, value_list)
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high
        self.lock = threading.Lock()
        self.is_running = False

    def trigger(self):
        if self.is_running:
            raise RuntimeError("Trigger is already running")
        with self.lock:
            if self.pulse_high:
                self.pi.hardware_PWM(self.pin, 2, self.pulse_duration, 0, self.pulse_duration)
            else:
                self.pi.hardware_PWM(self.pin, 2, self.pulse_duration, self.pulse_duration, 0)
            self.is_running = True

    def shutdown(self):
        super().shutdown()
        self.is_running = False

def signal_handler(sig, frame):
    for pin in [21, 20]:
        try:
            pin.shutdown()
        except Exception as e:
            print(f"Error shutting down pin {pin}: {e}")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    try:
        trigger_pin = TriggerPin(20, 100, pulse_high=True, value_list=(0, 1))
        trigger_pin.trigger()
        time.sleep(1)
    except Exception as e:
        print(f"Error: {e}")
    finally:
        trigger_pin.shutdown()

