import sys
import time
from gpiozero import LED
from queue import Queue
from collections import deque

def validate_grid(grid):
    """Validate the grid dimensions and content."""
    if not isinstance(grid, list) or not all(isinstance(row, list) for row in grid):
        raise ValueError("Grid must be a list of lists")
    if not all(len(row) == 5 for row in grid):
        raise ValueError("Grid must be a 5x5 list of lists")
    for row in grid:
        if not all(isinstance(cell, int) and cell in (0, 1) for cell in row):
            raise ValueError("Grid cells must be 0 or 1")
    return grid

def bfs(grid):
    """Perform breadth-first search on the grid."""
    start = (0, 0)
    end = (4, 4)
    if grid[start[0]][start[1]] == 1:
        return "Start cell is an obstacle"
    if grid[end[0]][end[1]] == 1:
        return "End cell is an obstacle"
    visited = set()
    queue = deque([(start, 0)])
    visited.add(start)
    while queue:
        current, steps = queue.popleft()
        if current == end:
            return steps
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            x, y = current[0] + dx, current[1] + dy
            if 0 <= x < 5 and 0 <= y < 5 and grid[x][y] == 0 and (x, y) not in visited:
                visited.add((x, y))
                queue.append(((x, y), steps + 1))
    return "No path found"

def main():
    try:
        grid = eval(input("Enter the 5x5 grid as a list of lists (0 for free space, 1 for obstacle): "))
        grid = validate_grid(grid)
        path_length = bfs(grid)
        if path_length is not None:
            print(f"Path length: {path_length}")
            # Simulate LED control
            led = LED(18)
            led.on()
            time.sleep(2)
            led.off()
        else:
            print(path_length)
            # Simulate LED control
            led = LED(18)
            for _ in range(3):
                led.blink(0.5, 0.5)
    except KeyboardInterrupt:
        print("Program interrupted")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Clean up GPIO resources
        try:
            led.close()
        except NameError:
            pass

if __name__ == "__main__":
    main()

