# Define GPIO pins for sensors and motors
SENSOR_LEFT = 5
SENSOR_RIGHT = 6
MOTOR_LEFT = 16
MOTOR_RIGHT = 26

# Define motor control functions
def motor_left_on():
    GPIO.output(MOTOR_LEFT, 1)

def motor_left_off():
    GPIO.output(MOTOR_LEFT, 0)

def motor_right_on():
    GPIO.output(MOTOR_RIGHT, 1)

def motor_right_off():
    GPIO.output(MOTOR_RIGHT, 0)

# Define sensor read functions
def sensor_read_left():
    try:
        return GPIO.input(SENSOR_LEFT)
    except Exception as e:
        print(f"Error reading left sensor: {e}")
        return None

def sensor_read_right():
    try:
        return GPIO.input(SENSOR_RIGHT)
    except Exception as e:
        print(f"Error reading right sensor: {e}")
        return None

# Define control logic
def control_logic():
    try:
        while True:
            left_sensor = sensor_read_left()
            right_sensor = sensor_read_right()

            if left_sensor is None or right_sensor is None:
                motor_left_off()
                motor_right_off()
            elif left_sensor and not right_sensor:
                motor_right_on()
                motor_left_off()
            elif not left_sensor and right_sensor:
                motor_left_on()
                motor_right_off()
            else:
                motor_left_on()
                motor_right_on()

            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Exiting...")
        GPIO.cleanup()

