import pigpio
import time
from enum import Enum
from typing import Union

class MotorError(Exception):
    """Base class for motor-related exceptions."""
    pass

class MotorState(Enum):
    """Enum for motor states."""
    STOPPED = 0
    RUNNING = 1

class Motor:
    """Class for controlling a DC motor using pigpio."""
    def __init__(self, pi: pigpio.pi, pin: int):
        """Initialize the motor with a pigpio instance and a GPIO pin."""
        self.pi = pi
        self.pin = pin
        self.state = MotorState.STOPPED
        self.frequency = 1000
        self.duty_cycle = 0

        try:
            self.pi.set_mode(pin, pigpio.OUTPUT)
            self.pi.set_PWM_frequency(pin, self.frequency)
        except pigpio.error as e:
            raise MotorError(f"Failed to initialize motor: {e}")

    def set_frequency(self, freq: int) -> None:
        """Set the PWM frequency."""
        try:
            self.pi.set_PWM_frequency(self.pin, freq)
        except pigpio.error as e:
            raise MotorError(f"Failed to set frequency: {e}")

    def set_duty_cycle(self, duty: int) -> None:
        """Set the duty cycle."""
        if not isinstance(duty, int) or not 0 <= duty <= 255:
            raise MotorError("Duty cycle must be an integer between 0 and 255")

        try:
            self.pi.set_PWM_dutycycle(self.pin, duty)
        except pigpio.error as e:
            raise MotorError(f"Failed to set duty cycle: {e}")

    def stop(self) -> None:
        """Stop the motor by setting the duty cycle to 0."""
        self.set_duty_cycle(0)
        self.state = MotorState.STOPPED

    def __del__(self) -> None:
        """Clean up resources on exit."""
        if self.pi is not None:
            self.pi.stop()

    def close(self) -> None:
        """Explicitly close the pigpio instance."""
        if self.pi is not None:
            self.pi.stop()

class MotorController:
    """Class for managing multiple motors."""
    def __init__(self):
        """Initialize the motor controller."""
        self.motors = {}

    def add_motor(self, motor: Motor) -> None:
        """Add a motor to the controller."""
        self.motors[motor.pin] = motor

    def get_motor(self, pin: int) -> Union[Motor, None]:
        """Get a motor by its GPIO pin."""
        return self.motors.get(pin)

    def stop_all_motors(self) -> None:
        """Stop all motors."""
        for motor in self.motors.values():
            motor.stop()

if __name__ == "__main__":
    # Example usage
    pi = pigpio.pi()  # Replace with your own pigpio instance
    if pi is None:
        raise MotorError("Failed to connect to pigpio")

    motor = Motor(pi, 18)
    print("Motor started")
    time.sleep(2)
    motor.set_frequency(500)
    motor.set_duty_cycle(128)
    print("Motor running")
    time.sleep(2)
    motor.stop()
    print("Motor stopped")
    pi.stop()

