        self.servos = {
            'base': AngularServo(17, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50),
            'shoulder': AngularServo(27, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50),
            'gripper': AngularServo(22, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)
