class GarageDoor:
    def __init__(self, state_pin):
        self.state = None
        self.state_pin = state_pin
        self.relay = None
        self.automationhat = None
        self.mqtt_client = None
        self.mqtt_topic = "garage_door"

    def connect_to_automationhat(self):
        try:
            self.automationhat = AutomationHat()
            self.relay = self.automationhat.relay.one
            self.relay.close()
            self.relay = self.automationhat.relay.one
            self.relay.close()
            self.relay.on_change(self.state_changed)
            self.relay.value = 0  # Start with relay OFF
            return True
        except Exception as e:
            logging.error(f"Failed to connect to Automation Hat: {e}")
            return False

    def state_changed(self, value, pin):
        self.state = value
        if value == 1:
            self.mqtt_client.publish(self.mqtt_topic, "door_closed")
        else:
            self.mqtt_client.publish(self.mqtt_topic, "door_open")

    def connect_to_mqtt(self, mqtt_host, mqtt_port, mqtt_user, mqtt_password):
        try:
            self.mqtt_client = Client()
            self.mqtt_client.connect(mqtt_host, mqtt_port)
            self.mqtt_client.username_pw_set(mqtt_user, mqtt_password)
            return True
        except Exception as e:
            logging.error(f"Failed to connect to MQTT: {e}")
            return False

    def start(self, automationhat, mqtt_host, mqtt_port, mqtt_user, mqtt_password):
        if not self.connect_to_automationhat():
            return
        if not self.connect_to_mqtt(mqtt_host, mqtt_port, mqtt_user, mqtt_password):
            return

        self.mqtt_client = Client()
        self.mqtt_client.connect(mqtt_host, mqtt_port)
        self.mqtt_client.username_pw_set(mqtt_user, mqtt_password)
        self.mqtt_client.on_message = self.mqtt_message

        self.mqtt_client.loop_start()

    def mqtt_message(self, client, userdata, msg):
        if msg.topic == self.mqtt_topic:
            if msg.payload == "open":
                self.open_door()
            elif msg.payload == "close":
                self.close_door()

    def open_door(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
        except Exception as e:
            logging.error(f"Failed to open door: {e}")

    def close_door(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
        except Exception as e:
            logging.error(f"Failed to close door: {e}")

    def run(self):
        try:
            while True:
                if self.automationhat is None:
                    logging.error("Automation Hat not connected")
                    break
                if self.state is None:
                    logging.error("State not initialized")
                    break
                if self.state == 1:
                    self.open_door()
                else:
                    self.close_door()
                time.sleep(1)
        except KeyboardInterrupt:
            self.relay.off()
            self.automationhat.relay.one.close()
            self.mqtt_client.loop_stop()
            self.mqtt_client.disconnect()
            sys.exit(0)
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            self.relay.off()
            self.automationhat.relay.one.close()
            self.mqtt_client.loop_stop()
            self.mqtt_client.disconnect()
            sys.exit(0)

