import serial
import minimalmodbus
import time
import signal
import sys

class ModbusServo:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.serial = None
        self.modbus = minimalmodbus.Modbus(serial.Serial(port=port, baudrate=baudrate, timeout=1), slave_address=slave_address)

    def _check_serial(self):
        if not self.serial:
            try:
                self.serial = serial.Serial(port=self.port, baudrate=self.baudrate, timeout=1)
            except serial.SerialException as e:
                raise ValueError(f"Serial port {self.port} not available: {e}")

    def _check_modbus(self):
        if not self.modbus:
            try:
                self.modbus = minimalmodbus.Modbus(serial.Serial(port=self.port, baudrate=self.baudrate, timeout=1), slave_address=self.slave_address)
            except minimalmodbus.ModbusException as e:
                raise ValueError(f"Modbus connection failed: {e}")

    def set_operation_mode(self, mode):
        self._check_serial()
        self._check_modbus()
        if not isinstance(mode, int) or not (0 <= mode <= 3):
            raise ValueError("Invalid operation mode (0-3)")
        self.modbus.write_register(0x3500, mode, function_code=1)

    def write_position_command(self, value):
        self._check_serial()
        self._check_modbus()
        if not isinstance(value, int) or not (-10000 <= value <= 10000):
            raise ValueError("Invalid position command (-10000 to 10000)")
        self.modbus.write_register(0x4000, value, function_code=1)

    def write_velocity_command(self, value):
        self._check_serial()
        self._check_modbus()
        if not isinstance(value, int) or not (-1000 <= value <= 1000):
            raise ValueError("Invalid velocity command (-1000 to 1000)")
        self.modbus.write_register(0x6F00, value, function_code=1)

    def read_position_feedback(self):
        self._check_serial()
        self._check_modbus()
        try:
            return self.modbus.read_registers(0x3700, 2, function_code=1)
        except minimalmodbus.ModbusException as e:
            raise ValueError(f"Modbus read error: {e}")

    def read_velocity_feedback(self):
        self._check_serial()
        self._check_modbus()
        try:
            return self.modbus.read_registers(0x3B00, 2, function_code=1)
        except minimalmodbus.ModbusException as e:
            raise ValueError(f"Modbus read error: {e}")

    def start(self):
        self._check_serial()
        self._check_modbus()
        self.modbus.write_register(0x3100, 0x000F, function_code=1)

    def stop(self):
        self._check_serial()
        self._check_modbus()
        self.modbus.write_register(0x3100, 0x0006, function_code=1)

    def read_status(self):
        self._check_serial()
        self._check_modbus()
        try:
            return self.modbus.read_register(0x3000, function_code=1)
        except minimalmodbus.ModbusException as e:
            raise ValueError(f"Modbus read error: {e}")

    def _signal_handler(self, signal, frame):
        self.stop()
        sys.exit(0)

def main():
    servo = ModbusServo()
    signal.signal(signal.SIGINT, servo._signal_handler)
    signal.signal(signal.SIGTERM, servo._signal_handler)
    try:
        servo.start()
        print("Servo started")
        servo.write_position_command(5000)
        print("Position set to 5000")
        time.sleep(2)
        servo.write_velocity_command(100)
        print("Velocity set to 100")
        time.sleep(2)
        servo.stop()
        print("Servo stopped")
        servo.read_status()
        print("Status:", servo.read_status())
    except Exception as e:
        print(f"Error: {e}")
    finally:
        servo.stop()
        sys.exit(0)

if __name__ == '__main__':
    main()

