import json
from flask import Flask, jsonify, request
from flask_cors import CORS
import serial
import time
import uuid

app = Flask(__name__)
CORS(app)

# In-memory data store
data = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False}
]

# Serial port settings
port = '/dev/ttyUSB0'
baud_rate = 9600
timeout = 0.1

def open_serial():
    """Open the serial port and return the port object."""
    try:
        return serial.Serial(port, baud_rate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def close_serial(port):
    """Close the serial port."""
    if port:
        port.close()

@app.route('/version')
def version():
    """Return the SCPI identification query result."""
    port = open_serial()
    if not port:
        return jsonify({"error": "Serial port could not be opened"}), 503
    try:
        port.write(b'*IDN?\n')
        time.sleep(0.1)
        response = port.read_all()
        port.close()
        return jsonify({"result": response.decode().strip() + "<br>"})
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return jsonify({"error": "Error reading from serial port"}), 503

@app.route('/getdata')
def getdata():
    """Return the full in-memory list as JSON."""
    return jsonify(data)

@app.route('/getset/<int:item_id>')
def getset(item_id):
    """Return the matching item as JSON or 404 if not found."""
    item = next((item for item in data if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return jsonify({"error": "Item not found"}), 404

@app.route('/getpost/<int:item_id>/<name>')
def getpost(item_id, name):
    """Append a new item using the given item_id and name, returning the updated list as JSON."""
    item_id = int(item_id)
    new_item = {"id": item_id, "name": name, "done": False}
    data.append(new_item)
    return jsonify(data)

@app.route('/postjson', methods=['GET', 'POST'])
def postjson():
    """Create a new item with an auto-incremented id, name defaulting to '', and done defaulting to False."""
    if request.method == 'POST':
        try:
            data = request.get_json()
            if not data:
                return jsonify({"error": "Invalid JSON"}), 400
            item_id = data.get('id', None)
            name = data.get('name', '')
            done = data.get('done', False)
            if item_id is not None and not isinstance(item_id, int):
                return jsonify({"error": "Invalid item_id"}), 400
            if name is None:
                return jsonify({"error": "Missing name"}), 400
            if not isinstance(done, bool):
                return jsonify({"error": "Invalid done value"}), 400
            new_item_id = max(item['id'] for item in data) + 1 if data else 1
            new_item = {"id": new_item_id, "name": name, "done": done}
            data.append(new_item)
            return jsonify(data)
        except Exception as e:
            print(f"Error processing POST request: {e}")
            return jsonify({"error": "Error processing POST request"}), 500
    else:
        return jsonify(data)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

import serial
import time
import sys
import signal

# Set up signal handler for KeyboardInterrupt
def signal_handler(sig, frame):
    print("Exiting...")
    sys.exit(0)

# Set up serial connection
def establish_serial_connection():
    try:
        ser = serial.Serial('/dev/rfcomm4', 38400, timeout=1)
        print("Serial connection established.")
        return ser
    except serial.SerialException as e:
        print(f"Error establishing serial connection: {e}")
        raise RuntimeError("Failed to establish serial connection")

# Send command to the device
def send_command(ser, command):
    try:
        ser.write(f'X{command}\n'.encode())
        time.sleep(0.1)  # 0.1 second delay
        response = ser.readline().decode().strip()
        if response:
            print(f"Received response: {response}")
        else:
            print("No response received.")
    except serial.SerialException as e:
        print(f"Error sending command: {e}")
        raise RuntimeError("Failed to send command")

# Main loop
def main():
    signal.signal(signal.SIGINT, signal_handler)  # Handle KeyboardInterrupt
    ser = establish_serial_connection()
    try:
        while True:
            command = input("Enter command (or 'exit' to quit): ")
            if command.lower() == 'exit':
                break
            send_command(ser, command)
    finally:
        if ser:
            ser.close()
            print("Serial connection closed.")

if __name__ == "__main__":
    main()
